mapper.select:
SELECT a.ANSWER_ID as answerId, a.QUESTION_ID as questionId, a.LAWYER_ID as lawyerId, a.CONTENT as content, a.IS_ADOPTED as isAdopted, a.CREATED_AT as createdAt, a.UPDATED_AT as updatedAt,
/* 회원 및 변호사 상세 정보 */ m.MEMBER_ID as memberId, -- 💡 추가: 프로필 이동용 ID m.NAME as lawyerName, -- 변호사 이름 l.OFFICE_NAME as officeName, -- 사무소 명 l.SPECIALTY as specialty, -- 전문 분야
/* 변호사 활동 지표 */ l.ADOPT_CNT as adoptCnt, -- 물리 컬럼 활용 (SELECT COUNT(*) FROM TB_ANSWER WHERE LAWYER_ID = l.LAWYER_ID) as answerCnt, -- 총 답변 수 계산
/* 프로필 이미지 */ att.SAVE_PATH as lawyerProfile
FROM TB_ANSWER a JOIN TB_LAWYER l ON a.LAWYER_ID = l.LAWYER_ID JOIN TB_MEMBER m ON l.MEMBER_ID = m.MEMBER_ID LEFT OUTER JOIN TB_ATTACHMENT att ON l.LAWYER_ID = att.REF_ID AND att.REF_TYPE = 'LAWYER' WHERE a.QUESTION_ID = #{questionId} ORDER BY a.IS_ADOPTED DESC, a.CREATED_AT ASC
